window.docContents[155].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Untyped-terms":{"contents":"\n\nSolver creation and typed terms with their smt! syntax extension.\n\nopen Untyped in\ndef setup : Env (Solver × Term × Term) := do\n  let solver ← Solver.new\n  solver.setOption \"produce-models\" \"true\"\n  let b1 ← Term.mkSymbolAs Bool \"b1\"\n  let i1 ← Term.mkSymbolAs Int \"i1\"\n  let formula ← smt! ¬ b1 ∨ (b1 ∧ 0 < i1)\n  solver.assert formula\n  return (solver, b1, i1)\n\n\nSimple check-sat.\n\n#eval Env.runIO do\n  let (solver, b1, i1) ← setup\n  println! \"check-sat\"\n  for f in ← solver.getAssertions do println! \"∧ {f}\"\n  let model? ← solver.checkSat?\n    (ifSat := do\n      let b1 ← solver.getValue b1\n      let i1 ← solver.getValue i1\n      return some #[b1, i1])\n  if let some model := model?\n  then println! \"→ sat {model}\"\n  else println! \"→ unsat\"\n\n\ncheck-sat\n∧ (or (not b1) (and b1 (< 0 i1)))\n→ sat #[false, 0]\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.2. Untyped terms","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Untyped-terms"}});